// Validates and normalizes the incoming search request. Deterministic, no external calls.
const DEFAULT_LIMIT = 10;
const MAX_LIMIT = 25;
const MAX_TEXT = 200;

const raw = $input.first().json || {};
let body = raw.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = null; }
}

const errors = [];
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  errors.push('Request body must be a JSON object.');
  body = {};
}

function optionalText(field) {
  const v = body[field];
  if (v === undefined || v === null) return null;
  if (typeof v === 'number') return String(v);
  if (typeof v !== 'string') { errors.push(field + ' must be a string.'); return null; }
  const t = v.trim();
  if (t.length === 0) return null;
  if (t.length > MAX_TEXT) { errors.push(field + ' must be at most ' + MAX_TEXT + ' characters.'); return null; }
  return t;
}

let query = null;
if (body.query === undefined || body.query === null) {
  errors.push('query is required.');
} else if (typeof body.query !== 'string') {
  errors.push('query must be a string.');
} else if (body.query.trim().length === 0) {
  errors.push('query must not be empty.');
} else if (body.query.trim().length > MAX_TEXT) {
  errors.push('query must be at most ' + MAX_TEXT + ' characters.');
} else {
  query = body.query.trim();
}

const cuisine = optionalText('cuisine');
const area = optionalText('area');
const restaurantName = optionalText('restaurant_name');

let maxItemPrice = null;
const mp = body.max_item_price;
if (mp !== undefined && mp !== null && mp !== '') {
  const n = typeof mp === 'number' ? mp : (typeof mp === 'string' ? Number(mp.replace(/,/g, '').trim()) : NaN);
  if (!Number.isFinite(n) || n <= 0) errors.push('max_item_price must be a positive number (PKR).');
  else maxItemPrice = n;
}

let limit = DEFAULT_LIMIT;
const lv = body.limit;
if (lv !== undefined && lv !== null && lv !== '') {
  const n = typeof lv === 'number' ? lv : (typeof lv === 'string' ? Number(lv.trim()) : NaN);
  if (!Number.isFinite(n) || !Number.isInteger(n) || n < 1) errors.push('limit must be a positive integer.');
  else limit = Math.min(n, MAX_LIMIT);
}

if (errors.length > 0) {
  return [{ json: {
    valid: false,
    statusCode: 400,
    body: {
      success: false,
      error: 'invalid_request',
      message: 'Invalid search request: ' + errors.join(' '),
      details: errors,
    },
  } }];
}

return [{ json: {
  valid: true,
  statusCode: 200,
  request: {
    query: query,
    cuisine: cuisine,
    area: area,
    restaurant_name: restaurantName,
    max_item_price: maxItemPrice,
    limit: limit,
  },
} }];

// Deterministic join + filter + rank. Never invents data: every field comes from the sheet rows.
try {
  const req = $('Validate Search Request').first().json.request;

  const isRealRow = function (i) { return i && i.json && Object.keys(i.json).length > 0; };
  const restaurantItems = $('Read Restaurants Sheet').all();
  const menuItems = $('Read Menu Items Sheet').all();
  const sheetFailed = restaurantItems.concat(menuItems).some(function (i) { return i && i.json && i.json.error; });
  if (sheetFailed) {
    return [{ json: { statusCode: 502, body: {
      success: false, error: 'database_unavailable',
      message: 'The restaurant database could not be read right now. Please try again shortly.'
    } } }];
  }

  const toBool = function (v) {
    if (v === true) return true;
    if (v === false || v === null || v === undefined) return false;
    if (typeof v === 'number') return v === 1;
    const s = String(v).trim().toLowerCase();
    return s === 'true' || s === 'yes' || s === 'y' || s === '1';
  };
  const str = function (v) { return v === null || v === undefined ? '' : String(v).trim(); };
  const norm = function (v) { return str(v).toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').trim(); };
  const idKey = function (v) { return str(v).toUpperCase(); };
  const parsePrice = function (v) {
    if (v === null || v === undefined || v === '') return null;
    if (typeof v === 'number') return Number.isFinite(v) && v >= 0 ? v : null;
    const cleaned = String(v).replace(/[^0-9.]/g, '');
    if (cleaned === '') return null;
    const n = Number(cleaned);
    return Number.isFinite(n) && n >= 0 ? n : null;
  };
  const STOP = ['a','an','the','i','me','my','we','want','would','like','some','any','please','from','in','at','of','for','with','and','or','to','near','order','get','food','dish','item','items','something','show','find'];
  const stem = function (t) { return t.length > 3 && t.endsWith('s') ? t.slice(0, -1) : t; };
  const tokens = function (v) { return norm(v).split(' ').filter(function (t) { return t && STOP.indexOf(t) === -1; }).map(stem); };
  const tokenSet = function (v) { return norm(v).split(' ').filter(Boolean).map(stem); };
  const allIn = function (qt, text) { if (!qt.length) return false; const ts = tokenSet(text); return qt.every(function (t) { return ts.indexOf(t) !== -1; }); };
  const contains = function (hay, needle) { const h = norm(hay), n = norm(needle); return n.length > 0 && h.length > 0 && (' ' + h + ' ').indexOf(' ' + n + ' ') !== -1; };
  const filterMatch = function (field, wanted) { const f = norm(field), w = norm(wanted); return f.length > 0 && (f.indexOf(w) !== -1 || w.indexOf(f) !== -1); };

  // Active restaurants, keyed by restaurant_id (first occurrence wins to avoid duplicates).
  const restaurants = {};
  restaurantItems.filter(isRealRow).forEach(function (i) {
    const r = i.json; const key = idKey(r.restaurant_id);
    if (!key || restaurants[key] || !toBool(r.is_active)) return;
    restaurants[key] = r;
  });

  const q = req.query; const qNorm = norm(q); const qTokens = tokens(q);
  const seen = {};
  const scored = [];

  menuItems.filter(isRealRow).forEach(function (i) {
    const m = i.json;
    const rKey = idKey(m.restaurant_id);
    const r = restaurants[rKey];
    if (!r || !toBool(m.is_available) || !str(m.item_name)) return;
    const dedupeKey = str(m.menu_item_id) ? 'id:' + idKey(m.menu_item_id) : 'nm:' + rKey + '|' + norm(m.item_name);
    if (seen[dedupeKey]) return;

    if (req.cuisine && !filterMatch(r.cuisine, req.cuisine)) return;
    if (req.area && !filterMatch(r.area, req.area)) return;
    if (req.restaurant_name && !filterMatch(r.restaurant_name, req.restaurant_name)) return;
    const price = parsePrice(m.price);
    if (req.max_item_price !== null && req.max_item_price !== undefined) {
      if (price === null || price > req.max_item_price) return;
    }

    const itemName = norm(m.item_name);
    let score = 0;
    if (qNorm && itemName === qNorm) score = 100;
    else if (contains(m.item_name, q)) score = 85;
    else if (allIn(qTokens, m.item_name)) score = 75;
    else if (itemName && contains(q, m.item_name)) score = 70;
    else if (contains(r.restaurant_name, q) || allIn(qTokens, r.restaurant_name)) score = 55;
    else if (contains(m.category, q) || allIn(qTokens, m.category) || (norm(m.category) && contains(q, m.category))) score = 45;
    else if (contains(r.cuisine, q) || allIn(qTokens, r.cuisine) || (norm(r.cuisine) && contains(q, r.cuisine))) score = 40;
    else if (contains(r.specialty, q) || allIn(qTokens, r.specialty)) score = 35;
    else if (contains(m.description, q) || allIn(qTokens, m.description)) score = 30;
    else if (contains(r.area, q) || allIn(qTokens, r.area)) score = 25;
    else if (qTokens.length > 1) {
      const combined = tokenSet([m.item_name, m.category, m.description, r.restaurant_name, r.cuisine, r.specialty, r.area].join(' '));
      const hits = qTokens.filter(function (t) { return combined.indexOf(t) !== -1; }).length;
      const ratio = hits / qTokens.length;
      if (ratio >= 0.5) score = Math.round(10 + 10 * ratio);
    }
    if (score === 0) return;
    const signature = toBool(m.is_signature_item);
    if (signature) score += 3;

    seen[dedupeKey] = true;
    scored.push({ score: score, result: {
      restaurant_id: str(r.restaurant_id),
      restaurant_name: str(r.restaurant_name),
      cuisine: str(r.cuisine),
      restaurant_area: str(r.area),
      menu_item_id: str(m.menu_item_id),
      item_name: str(m.item_name),
      category: str(m.category),
      description: str(m.description),
      price: price,
      currency: 'PKR',
      is_available: true,
      is_vegetarian: toBool(m.is_vegetarian),
      spice_level: str(m.spice_level),
      is_signature_item: signature,
      serving_size: str(m.serving_size)
    } });
  });

  scored.sort(function (a, b) {
    if (b.score !== a.score) return b.score - a.score;
    if (a.result.is_signature_item !== b.result.is_signature_item) return a.result.is_signature_item ? -1 : 1;
    const pa = a.result.price === null ? Infinity : a.result.price;
    const pb = b.result.price === null ? Infinity : b.result.price;
    if (pa !== pb) return pa - pb;
    const rn = a.result.restaurant_name.localeCompare(b.result.restaurant_name);
    if (rn !== 0) return rn;
    return a.result.item_name.localeCompare(b.result.item_name);
  });

  const results = scored.slice(0, req.limit).map(function (s) { return s.result; });
  const filtersApplied = {};
  ['cuisine', 'area', 'restaurant_name', 'max_item_price'].forEach(function (k) { if (req[k] !== null && req[k] !== undefined) filtersApplied[k] = req[k]; });

  return [{ json: { statusCode: 200, body: {
    success: true,
    query: q,
    filters: filtersApplied,
    count: results.length,
    total_matches: scored.length,
    results: results,
    message: results.length > 0
      ? 'Matching menu items found. Opening hours are not checked; availability reflects the database only.'
      : 'No matching menu items found. Try a different dish, cuisine or restaurant name, or remove some filters.'
  } } }];
} catch (err) {
  return [{ json: { statusCode: 500, body: {
    success: false, error: 'internal_error',
    message: 'Something went wrong while searching the menu. Please try again.'
  } } }];
}
